const state = $getWorkflowStaticData('global');
state.seen = state.seen || [];
const premierPassage = state.seen.length === 0 && !state.assoHash;
const strip = (s) => (s || '').replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&#x27;|&#39;/g, "'").replace(/\s+/g, ' ').trim();

const html = String($('Tailharbor - bassets').first().json.data || '');
const re = /<a\b([^>]*?)href="(\/fr\/animaux\/[^"]+)"([^>]*)>([\s\S]*?)<\/a>/gi;
const parLien = {};
let m;
while ((m = re.exec(html)) !== null) {
  const href = m[2];
  const attrs = m[1] + ' ' + m[3] + ' ' + m[4];
  const alts = [...attrs.matchAll(/(?:alt|title|aria-label)="([^"]*)"/gi)].map(x => x[1]);
  const texte = (strip(m[4]) + ' ' + alts.join(' ')).trim();
  parLien[href] = ((parLien[href] || '') + ' ' + texte).trim();
}

const nouveaux = [];
for (const [href, texte] of Object.entries(parLien)) {
  const t = texte.toLowerCase();
  const estBasset = t.includes('basset') || href.includes('basset');
  const estMale = /\bmale\b|\bmâle\b/.test(t) && !/female|femelle/.test(t);
  const estChiot = /puppy|chiot/.test(t);
  if (!estBasset || !estMale || estChiot) continue;
  if (state.seen.includes(href)) continue;
  state.seen.push(href);
  nouveaux.push({ titre: texte.slice(0, 200), lien: 'https://tailharbor.eu' + href });
}
state.seen = state.seen.slice(-500);

const assoHtml = String($('Un coeur sous l oreille - page adoption').first().json.data || '');
const assoTexte = strip(assoHtml.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ''));
let h = 0;
for (let i = 0; i < assoTexte.length; i++) { h = ((h << 5) - h + assoTexte.charCodeAt(i)) | 0; }
const assoHash = String(h);
const assoChange = assoTexte.length > 0 && !!state.assoHash && state.assoHash !== assoHash;
if (assoTexte.length > 0) state.assoHash = assoHash;

const liste = (arr) => '<ul>' + arr.map(n => '<li><a href="' + n.lien + '">' + n.titre + '</a></li>').join('') + '</ul>';

if (premierPassage) {
  return [{ json: { envoyer: true, sujet: 'Veille basset : démarrage', html: '<p>La veille est en place. ' + nouveaux.length + ' annonce(s) de mâles déjà en ligne ont été mémorisées :</p>' + liste(nouveaux) + '<p>Ensuite, un mail seulement s il y a du nouveau.</p>' } }];
}

const envoyer = nouveaux.length > 0 || assoChange;
let corps = '';
if (nouveaux.length) corps += '<h3>Nouveaux bassets mâles à adopter (' + nouveaux.length + ')</h3>' + liste(nouveaux) + '<p><i>Vérifie la localisation : Tailharbor liste aussi des refuges hors de France.</i></p>';
if (assoChange) corps += '<h3>La page adoption de Un coeur sous l oreille a changé</h3><p><a href="https://www.un-coeur-sous-loreille.org/sauvetage.html">Voir la page</a> (pense aussi à leur groupe Facebook).</p>';
return [{ json: { envoyer, sujet: 'Veille basset : ' + (nouveaux.length ? nouveaux.length + ' nouveau(x) mâle(s)' : 'page association modifiée'), html: corps } }];
